package com.englishhero.practice;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.ObjectMapper;
import com.englishhero.identity.SessionPrincipal;
import com.englishhero.reading.*;
import com.englishhero.reading.quiz.QuizDtos;
import com.englishhero.reading.quiz.QuizRules;
import com.englishhero.web.BusinessException;
import static com.englishhero.practice.PracticeDtos.*;
@Service
@Transactional(isolation=Isolation.READ_COMMITTED)
public class PracticeAdminService {
 private final PracticeSubjectiveAdminService subjective;private final PracticeSetMapper sets;private final PracticeQuizMapper quizzes;private final ArticleMapper articles;private final AdminArticleService admin;private final PracticePublicationChecks checks;private final ObjectMapper json;private final PracticeAudioService audio;
 public PracticeAdminService(PracticeSetMapper sets,PracticeQuizMapper quizzes,ArticleMapper articles,AdminArticleService admin,PracticePublicationChecks checks,ObjectMapper json,PracticeAudioService audio,PracticeSubjectiveAdminService subjective){this.subjective=subjective;this.audio=audio;this.sets=sets;this.quizzes=quizzes;this.articles=articles;this.admin=admin;this.checks=checks;this.json=json;}
 static BusinessException missing(){return new BusinessException(404,"PRACTICE_NOT_FOUND","题组或练习不存在，或暂不可访问");}
 static void lock(Integer expected,int actual){if(expected==null||expected<0)throw BusinessException.invalid("expectedLockVersion","请提供当前版本");if(expected!=actual)throw new BusinessException(409,"PRACTICE_CONFLICT","内容已在其他页面更新，请加载最新版本后编辑");}
 public ReadingDtos.PageDto<AdminSet> list(SessionPrincipal actor,Query query){admin.requireAdmin(actor);return new ReadingDtos.PageDto<>(sets.list(query,true,actor.userId()).stream().map(this::dto).toList(),query.page(),query.pageSize(),sets.count(query,true,actor.userId()));}
 public AdminSet get(SessionPrincipal actor,String id){admin.requireAdmin(actor);var r=sets.get(ArticleRules.id(id,"setId"),false);if(r==null)throw missing();return dto(r);}
 public AdminSet create(SessionPrincipal actor,DraftInput input){admin.requireAdmin(actor);var d=PracticeDraftRules.normalize(input);if(d.listening()!=null&&d.listening().audioAssetId()!=null)audio.requireOwnedAsset(actor,d.listening().audioAssetId());long aid=ArticleRules.id(d.articleId(),"articleId"),vid=ArticleRules.id(d.articleVersionId(),"articleVersionId");if(articles.article(aid,true)==null||articles.version(aid,vid)==null)throw missing();if("LISTENING".equals(d.readingType())&&!articles.practiceOnly(aid))throw BusinessException.invalid("articleId","听力配套原文必须使用专项专用材料，不能复用公开阅读文章");var existing=sets.forArticle(aid);if(existing!=null)throw new BusinessException(409,"PRACTICE_ALREADY_EXISTS","这篇文章已有专项题组，请打开已有草稿",Map.of("existingSetId",""+existing.id()));long quiz=quizzes.draft(aid,vid,d.questions(),actor.userId());long id=sets.create(aid,vid,quiz,d.readingType(),json.writeValueAsString(new DraftState(d.metadata(),Map.of(),null,d.readingType(),d.wordBank(),d.listening())),actor.userId());return dto(sets.get(id,false));}
 private PracticeSetMapper.Row locked(String id){var before=sets.get(ArticleRules.id(id,"setId"),false);if(before==null)throw missing();if(articles.article(before.articleId(),true)==null)throw missing();var latest=sets.get(before.id(),false);if(quizzes.get(latest.quizId(),true)==null)throw missing();return sets.get(before.id(),true);}
 public AdminSet save(SessionPrincipal actor,String id,DraftInput input){admin.requireAdmin(actor);var d=PracticeDraftRules.normalize(input);if(d.listening()!=null&&d.listening().audioAssetId()!=null)audio.requireOwnedAsset(actor,d.listening().audioAssetId());var r=locked(id);if("LISTENING".equals(r.readingType())&&!articles.practiceOnly(r.articleId()))throw BusinessException.invalid("articleId","听力配套原文必须使用专项专用材料");lock(d.expectedLockVersion(),r.lockVersion());if(!Objects.equals(r.readingType(),d.readingType()))throw BusinessException.invalid("readingType","题组创建后题型不可更改");if(r.articleId()!=ArticleRules.id(d.articleId(),"articleId"))throw BusinessException.invalid("articleId","题组绑定文章保持不变；其他文章请新建题组，已有版本保留");long vid=ArticleRules.id(d.articleVersionId(),"articleVersionId");if(articles.version(r.articleId(),vid)==null)throw missing();var old=state(r);var reviews=new LinkedHashMap<String,String>();boolean sameAudio=Objects.equals(old.listening()==null?null:new ListeningData(old.listening().audioAssetId(),old.listening().groups(),false),d.listening());if(vid==r.articleVersionId()&&sameAudio)for(var q:d.questions())if(Objects.equals(old.reviews().get(q.key()),checks.questionHash(q,d.readingType(),d.wordBank())))reviews.put(q.key(),old.reviews().get(q.key()));String groupHash=checks.sourceHash(vid,d.metadata(),d.questions(),d.readingType(),d.wordBank(),d.listening());String sourceReview=Objects.equals(groupHash,old.sourceReview())?groupHash:null;long quiz=quizzes.draft(r.articleId(),vid,d.questions(),actor.userId());sets.save(r,vid,quiz,json.writeValueAsString(new DraftState(d.metadata(),reviews,sourceReview,d.readingType(),d.wordBank(),sameAudio?old.listening():d.listening())),actor.userId());return dto(sets.get(r.id(),false));}
 public AdminSet review(SessionPrincipal actor,String id,ReviewInput input){admin.requireAdmin(actor);if(input==null||input.reviewed()==null)throw BusinessException.invalid("reviewed","请选择确认状态");var before=sets.get(ArticleRules.id(id,"setId"),false);if(before!=null&&PracticeSubjectiveRules.isSubjective(before.readingType()))return subjective.review(actor,id,input);var r=locked(id);lock(input.expectedLockVersion(),r.lockVersion());var qs=quizzes.questions(quizzes.get(r.quizId(),false));var state=state(r);var reviews=new LinkedHashMap<>(state.reviews());String source=state.sourceReview();var listening=state.listening();
  if("QUESTION".equals(input.kind())){var q=qs.stream().filter(x->Objects.equals(x.key(),input.questionKey())).findFirst().orElseThrow(()->BusinessException.invalid("questionKey","题目不存在"));if(input.reviewed()){requireNoIssues(checks.question(q,r.readingType(),state.wordBank()));reviews.put(q.key(),checks.questionHash(q,r.readingType(),state.wordBank()));}else reviews.remove(q.key());source=null;}
  else if("QUESTIONS".equals(input.kind())&&input.questionKey()==null){
   if(input.reviewed()){
    var issues=allChecks(r,state,qs).stream().filter(c->!c.path().equals("sourceReview")&&!c.path().startsWith("metadata.")&&!c.path().endsWith(".review")).toList();
    requireNoIssues(issues);
    for(var q:qs)reviews.put(q.key(),checks.questionHash(q,r.readingType(),state.wordBank()));
   }else reviews.clear();
   source=null;
  }
  else if("AUDIO".equals(input.kind())&&"LISTENING".equals(r.readingType())&&listening!=null){
   if(input.reviewed()){audio.requireOwnedAsset(actor,listening.audioAssetId());if(listening.groups().isEmpty()||qs.isEmpty())throw BusinessException.invalid("listening.groups","先完成整套题目和分组");}
   listening=new ListeningData(listening.audioAssetId(),listening.groups(),input.reviewed());source=null;
  }
  else if("SOURCE".equals(input.kind())&&input.questionKey()==null){if(input.reviewed()){requireNoIssues(checks.source(r.articleVersionId(),state,qs,r.readingType(),articleBody(r.articleId(),r.articleVersionId())));source=checks.sourceHash(r.articleVersionId(),state.metadata(),qs,r.readingType(),state.wordBank(),state.listening());}else source=null;}
  else throw BusinessException.invalid("kind","请选择单题、整组题目或文章来源校对");
  sets.review(r,json.writeValueAsString(new DraftState(state.metadata(),reviews,source,r.readingType(),state.wordBank(),listening)),actor.userId());return dto(sets.get(r.id(),false));
 }
 public AdminSet publish(SessionPrincipal actor,String id,Integer expected){admin.requireAdmin(actor);var before=sets.get(ArticleRules.id(id,"setId"),false);if(before!=null&&PracticeSubjectiveRules.isSubjective(before.readingType()))return subjective.publish(actor,id,expected);var r=locked(id);lock(expected,r.lockVersion());var quiz=quizzes.get(r.quizId(),false);var qs=quizzes.questions(quiz);var state=state(r);var issues=allChecks(r,state,qs);requireNoIssues(issues);var validated="LISTENING".equals(r.readingType())?PracticeListeningRules.questions(qs):"CLOZE".equals(r.readingType())?PracticeClozeRules.normalizeQuestions(qs):"MATCH".equals(r.readingType())?PracticeMatchRules.normalizeQuestions(qs):QuizRules.questions(new QuizDtos.Input(qs,expected));long version=quizzes.publish(quiz,validated,actor.userId());String bank="CLOZE".equals(r.readingType())?json.writeValueAsString(state.wordBank()):null;sets.publish(r,version,r.readingType(),bank,json.writeValueAsString(state.metadata()),actor.userId(),state.listening());return dto(sets.get(r.id(),false));}
 public AdminSet unpublish(SessionPrincipal actor,String id,Integer expected){admin.requireAdmin(actor);var before=sets.get(ArticleRules.id(id,"setId"),false);if(before!=null&&PracticeSubjectiveRules.isSubjective(before.readingType()))return subjective.unpublish(actor,id,expected);var r=locked(id);lock(expected,r.lockVersion());if(r.publishedVersionId()==null)throw missing();sets.unpublish(r,actor.userId());return dto(sets.get(r.id(),false));}
 public ReadingDtos.PageDto<PublishedVersion> versions(SessionPrincipal actor,String id,int page,int size){admin.requireAdmin(actor);ArticleRules.page(page);ArticleRules.pageSize(size);var r=sets.get(ArticleRules.id(id,"setId"),false);if(r==null)throw missing();return new ReadingDtos.PageDto<>(sets.versions(r.id(),page,size).stream().map(this::publishedDto).toList(),page,size,r.revision());}
 public PublishedVersion version(SessionPrincipal actor,String id,int revision){admin.requireAdmin(actor);var v=sets.revision(ArticleRules.id(id,"setId"),revision);if(v==null)throw missing();return publishedDto(v);}
 PublishedVersion publishedDto(PracticeSetMapper.Version v){if(PracticeSubjectiveRules.isSubjective(v.readingType()))return subjective.publishedDto(v);var qs=quizzes.published(v.quizVersionId());var result=new ArrayList<QuizDtos.QuestionInput>();for(int i=0;i<qs.size();i++){var q=qs.get(i);result.add(new QuizDtos.QuestionInput(q.key(),q.type(),q.stem(),q.options(),q.answer(),q.explanation(),i));}return new PublishedVersion(v.revision(),v.publishedAt(),json.readValue(v.metadata(),Metadata.class),admin.version(v.articleId(),v.articleVersionId()),result,v.readingType(),wordBank(v.wordBankJson()),publishedListening(v.id()));}
 private ListeningData publishedListening(long id){String value=sets.listening(id);return value==null?null:json.readValue(value,ListeningData.class);}
 DraftState state(PracticeSetMapper.Row r){var value=json.readValue(r.metadata(),DraftState.class);return new DraftState(value.metadata(),value.reviews()==null?Map.of():value.reviews(),value.sourceReview(),r.readingType(),value.wordBank()==null?List.of():value.wordBank(),value.listening());}
 private String articleBody(long article,long version){var source=articles.version(article,version);if(source==null)return "";var document=json.readValue(source.contentJson(),ArticleContent.Document.class);return document.paragraphs().stream().map(p->p.sentences().stream().map(ArticleContent.Sentence::text).reduce((a,b)->a+"\n"+b).orElse("")).reduce((a,b)->a+"\n\n"+b).orElse("");}
 private List<Check> allChecks(PracticeSetMapper.Row r,DraftState state,List<QuizDtos.QuestionInput> qs){var result=new ArrayList<>(checks.all(r.articleVersionId(),state,qs,r.readingType(),articleBody(r.articleId(),r.articleVersionId())));var article=articles.article(r.articleId(),false);if(article==null||articles.version(r.articleId(),r.articleVersionId())==null)result.add(new Check("article",null,"请保存有效的专项原文"));if("LISTENING".equals(r.readingType())){
  if(!articles.practiceOnly(r.articleId()))result.add(new Check("articleId",null,"听力配套原文必须使用专项专用材料"));var data=state.listening();if(data==null||data.audioAssetId()==null)result.add(new Check("listening.audioAssetId",null,"请上传完整MP3音频"));else try{audio.asset(Long.parseLong(data.audioAssetId()));}catch(RuntimeException e){result.add(new Check("listening.audioAssetId",null,"音频文件不可访问，请重新上传"));}
  if(data==null||!Boolean.TRUE.equals(data.audioReviewed()))result.add(new Check("listening.audioReviewed",null,"尚未确认整套音频预听"));
 }return result;}
 private List<String> wordBank(String jsonValue){return jsonValue==null?List.of():List.of(json.readValue(jsonValue,String[].class));}
 AdminSet dto(PracticeSetMapper.Row r){if(PracticeSubjectiveRules.isSubjective(r.readingType()))return subjective.dto(r);var state=state(r);var qs=quizzes.questions(quizzes.get(r.quizId(),false));return new AdminSet(""+r.id(),""+r.articleId(),""+r.articleVersionId(),r.exam(),r.readingType(),state.metadata(),qs,qs.stream().filter(q->Objects.equals(state.reviews().get(q.key()),checks.questionHash(q,r.readingType(),state.wordBank()))).map(QuizDtos.QuestionInput::key).toList(),Objects.equals(state.sourceReview(),checks.sourceHash(r.articleVersionId(),state.metadata(),qs,r.readingType(),state.wordBank(),state.listening())),r.status(),r.revision(),r.lockVersion(),admin.version(r.articleId(),r.articleVersionId()),allChecks(r,state,qs),articles.practiceOnly(r.articleId()),state.wordBank(),state.listening());}
 private void requireNoIssues(List<Check> issues){if(!issues.isEmpty()){var fields=new LinkedHashMap<String,String>();for(var issue:issues)fields.putIfAbsent(issue.path(),issue.message());throw new BusinessException(400,"PRACTICE_REVIEW_REQUIRED","请完成内容检查和逐题校对",fields);}}
}
